--
-- Name: can_user_action(bigint, character varying, bigint); Type: FUNCTION; Schema: access_control; Owner: -
--

CREATE FUNCTION access_control.can_user_action(p_id_user bigint, p_permission_key character varying, p_id_status bigint DEFAULT NULL::bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM access_control.user_role ur
        JOIN access_control.role_permission_by_status rps
            ON rps.id_role = ur.id_role
        WHERE ur.id_user    = p_id_user
          AND ur.is_active  = true
          AND rps.permission_key = p_permission_key
          AND rps.is_allowed     = true
          AND rps.is_active      = true
          AND (rps.id_status IS NULL OR rps.id_status = p_id_status)
    );
$$;


--
-- Name: FUNCTION can_user_action(p_id_user bigint, p_permission_key character varying, p_id_status bigint); Type: COMMENT; Schema: access_control; Owner: -
--

COMMENT ON FUNCTION access_control.can_user_action(p_id_user bigint, p_permission_key character varying, p_id_status bigint) IS 'Verifica si un usuario tiene permiso para una acción en el estado actual de la venta.
Uso: SELECT access_control.can_user_action(42, ''sales.order.edit.field'', 3);
p_id_status NULL = verificar permiso sin considerar estado (permisos globales).';


--
-- Name: fn_update_article_counters(); Type: FUNCTION; Schema: knowledge_base; Owner: -
--

CREATE FUNCTION knowledge_base.fn_update_article_counters() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_helpful THEN
        UPDATE knowledge_base.kb_article
        SET helpful_count = helpful_count + 1
        WHERE id_article = NEW.id_article;
    ELSE
        UPDATE knowledge_base.kb_article
        SET not_helpful_count = not_helpful_count + 1
        WHERE id_article = NEW.id_article;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: search_articles(text, bigint, bigint, character varying, integer); Type: FUNCTION; Schema: knowledge_base; Owner: -
--

CREATE FUNCTION knowledge_base.search_articles(p_query text, p_id_user bigint DEFAULT NULL::bigint, p_id_cmpg bigint DEFAULT NULL::bigint, p_content_type character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 10) RETURNS TABLE(id_article bigint, title character varying, summary text, content_type character varying, category_name character varying, relevance real, is_pinned boolean, helpful_pct numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        a.id_article,
        a.title,
        a.summary,
        a.content_type,
        c.name AS category_name,
        ts_rank(
            to_tsvector('spanish', a.title || ' ' || COALESCE(a.summary,'') || ' ' || a.content),
            plainto_tsquery('spanish', p_query)
        ) AS relevance,
        a.is_pinned,
        CASE
            WHEN (a.helpful_count + a.not_helpful_count) = 0 THEN NULL
            ELSE ROUND(100.0 * a.helpful_count / (a.helpful_count + a.not_helpful_count), 1)
        END AS helpful_pct
    FROM knowledge_base.kb_article a
    JOIN knowledge_base.kb_category c ON c.id_category = a.id_category
    WHERE a.is_published = true
      AND (a.deprecated_at IS NULL OR a.deprecated_at > CURRENT_TIMESTAMP)
      AND (p_id_cmpg IS NULL OR a.id_cmpg IS NULL OR a.id_cmpg = p_id_cmpg)
      AND (p_content_type IS NULL OR a.content_type = p_content_type)
      AND to_tsvector('spanish', a.title || ' ' || COALESCE(a.summary,'') || ' ' || a.content)
          @@ plainto_tsquery('spanish', p_query)
    ORDER BY a.is_pinned DESC, relevance DESC
    LIMIT p_limit;
$$;


--
-- Name: FUNCTION search_articles(p_query text, p_id_user bigint, p_id_cmpg bigint, p_content_type character varying, p_limit integer); Type: COMMENT; Schema: knowledge_base; Owner: -
--

COMMENT ON FUNCTION knowledge_base.search_articles(p_query text, p_id_user bigint, p_id_cmpg bigint, p_content_type character varying, p_limit integer) IS 'Búsqueda full-text en artículos publicados con ranking por relevancia.
Uso: SELECT * FROM knowledge_base.search_articles(''m6 titular'', null, 5);
helpful_pct = % de usuarios que marcaron el artículo como útil.';


--
-- Name: convert_presale_to_order(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: lead_service; Owner: -
--

CREATE FUNCTION lead_service.convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint DEFAULT 1) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_presale   lead_service.lead_pre_sale%ROWTYPE;
    v_lead_id   BIGINT;
    v_order_id  BIGINT;
    v_status_id BIGINT;
BEGIN
    SELECT * INTO v_presale FROM lead_service.lead_pre_sale
    WHERE id_presale = p_id_presale AND id_status NOT IN (
        SELECT id_status FROM lead_service.pre_sale_status WHERE is_terminal = true
    );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Pre-venta % no encontrada o ya cerrada', p_id_presale;
    END IF;

    -- Obtener status inicial de lead
    SELECT id_sts INTO v_status_id FROM lead_service.lead_status
    WHERE category = 'OPEN' ORDER BY order_index LIMIT 1;

    -- Crear el lead formal
    INSERT INTO lead_service.lead
        (id_cmpg, id_src, first_name, last_name, phone,
         raw_data, current_status_id, assigned_user_id, register)
    VALUES
        (p_id_cmpg, p_id_src, v_presale.first_name, v_presale.last_name,
         v_presale.phone,
         jsonb_build_object(
             'from_presale', p_id_presale,
             'operator', v_presale.operator,
             'address', v_presale.address,
             'province', v_presale.province,
             'tentative_offer', v_presale.tentative_offer
         ),
         v_status_id, p_id_user, CURRENT_TIMESTAMP)
    RETURNING id_lead INTO v_lead_id;

    -- Marcar pre-sale como convertido
    UPDATE lead_service.lead_pre_sale SET
        id_status            = (SELECT id_status FROM lead_service.pre_sale_status WHERE code = 'CONVERTIDO'),
        converted_to_order_id = v_lead_id,
        converted_at         = CURRENT_TIMESTAMP,
        converted_by         = p_id_user
    WHERE id_presale = p_id_presale;

    RETURN v_lead_id;
END;
$$;


--
-- Name: FUNCTION convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint); Type: COMMENT; Schema: lead_service; Owner: -
--

COMMENT ON FUNCTION lead_service.convert_presale_to_order(p_id_presale bigint, p_id_cmpg bigint, p_id_user bigint, p_id_src bigint) IS 'Convierte un pre-sale en un lead formal trayendo todos los datos
enriquecidos. Los datos del pre-sale viajan como raw_data para
que el asesor solo complete los campos faltantes.
Uso: SELECT lead_service.convert_presale_to_order(123, 5, 42, 1);';


--
-- Name: fn_log_lead_status_change(); Type: FUNCTION; Schema: lead_service; Owner: -
--

CREATE FUNCTION lead_service.fn_log_lead_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_actor BIGINT;
BEGIN
    IF OLD.current_status_id IS DISTINCT FROM NEW.current_status_id THEN
        -- Intenta leer el usuario real de la sesión
        BEGIN
            v_actor := current_setting('app.current_user_id', true)::BIGINT;
        EXCEPTION WHEN OTHERS THEN
            v_actor := NEW.assigned_user_id;  -- fallback
        END;

        INSERT INTO lead_service.lead_tracking
            (id_lead, previous_status_id, new_status_id, id_user, comments, register)
        VALUES
            (NEW.id_lead, OLD.current_status_id, NEW.current_status_id,
             v_actor, 'Cambio de estado automático', CURRENT_TIMESTAMP);
    END IF;
    RETURN NEW;
END;
$$;


