--
-- Name: calcular_minutos_sla_colaborador(bigint, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: nxf_sla; Owner: -
--

CREATE FUNCTION nxf_sla.calcular_minutos_sla_colaborador(p_id_user bigint, p_created_at timestamp with time zone, p_resolved_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_day_of_week INT;
    v_shift_start TIME;
    v_shift_end TIME;
    v_limit_of_day TIMESTAMP WITH TIME ZONE;
    v_start_limit TIMESTAMP WITH TIME ZONE;
    v_effective_start TIMESTAMP WITH TIME ZONE;
    v_effective_end TIMESTAMP WITH TIME ZONE;
    v_minutes INT := 0;
BEGIN
    v_day_of_week := EXTRACT(DOW FROM p_created_at);

    SELECT start_time, end_time INTO v_shift_start, v_shift_end
    FROM nxf_sla.user_work_shifts
    WHERE id_user = p_id_user AND day_of_week = v_day_of_week AND is_active = true;

    IF NOT FOUND THEN
        v_shift_start := '08:00:00'::TIME;
        v_shift_end := '17:00:00'::TIME;
    END IF;

    v_start_limit := p_created_at::DATE + v_shift_start;
    v_limit_of_day := p_created_at::DATE + v_shift_end;

    IF p_created_at >= v_limit_of_day THEN
        RETURN 0;
    END IF;

    v_effective_start := GREATEST(p_created_at, v_start_limit);

    IF p_resolved_at > v_limit_of_day THEN
        v_effective_end := v_limit_of_day;
    ELSIF p_resolved_at < v_effective_start THEN
        v_effective_end := v_effective_start;
    ELSE
        v_effective_end := p_resolved_at;
    END IF;

    v_minutes := EXTRACT(EPOCH FROM (v_effective_end - v_effective_start)) / 60;
    RETURN GREATEST(v_minutes, 0);
END;
$$;


--
-- Name: fn_evaluate_applicant_rules(); Type: FUNCTION; Schema: recruitment_service; Owner: -
--

CREATE FUNCTION recruitment_service.fn_evaluate_applicant_rules() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_profile_data jsonb;
    v_is_rejected boolean := false;
    v_rejection_reason text := '';
BEGIN
    -- Obtenemos los datos del profile_data de la tabla APPLICANT relacionada
    SELECT profile_data INTO v_profile_data FROM recruitment_service.applicant WHERE id_applc = NEW.id_applc;

    -- REGLA 1: Disponibilidad Inmediata
    IF (v_profile_data->>'┬┐Estás disponible para iniciar de inmediato?' = 'No') THEN
        v_is_rejected := true;
        v_rejection_reason := v_rejection_reason || '[Sin Disp. Inmediata] ';
    END IF;

    -- REGLA 2: Descanso Sábados/Domingos/Feriados
    IF (v_profile_data->>'┬┐Tienes disponibilidad para descansar sábados, domingos y feriados españoles?' = 'No') THEN
        v_is_rejected := true;
        v_rejection_reason := v_rejection_reason || '[Sin Disp. Feriados] ';
    END IF;

    -- REGLA 3: Horario 6:15 a 3:15
    IF (v_profile_data->>'┬┐Puedes trabajar en el horario de 6:15 a.m. a 3:15 p.m.?' = 'No') THEN
        v_is_rejected := true;
        v_rejection_reason := v_rejection_reason || '[Sin Disp. Horario Madrugada] ';
    END IF;

    IF v_is_rejected THEN
        -- Seteamos directamente los valores en el registro NEW (antes de insertar)
        NEW.state := 3;
        NEW.is_active := false;
        NEW.channel_source := COALESCE(NEW.channel_source, '') || ' | AUTO-REJECT: ' || v_rejection_reason;
    ELSE
        -- Seteamos a Aprobado
        NEW.state := 2;
    END IF;
    
    RETURN NEW;
END;
$$;


