--
-- Name: fn_log_ecosystem_trajectory(bigint, integer, text); Type: FUNCTION; Schema: recruitment_service; Owner: -
--

CREATE FUNCTION recruitment_service.fn_log_ecosystem_trajectory(p_related_id bigint, p_id_evty integer, p_related_table text DEFAULT 'job_application'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM ext_ecosystem.user_trajectory 
        WHERE id_evty = p_id_evty 
          AND related_id = p_related_id
          AND related_table = p_related_table
    ) THEN
        INSERT INTO ext_ecosystem.user_trajectory (
            id_user, id_evty, event_date, related_schema, related_table, related_id, state, register_at
        ) VALUES (
            NULL, p_id_evty, CURRENT_DATE, 'recruitment_service', p_related_table, p_related_id, true, now()
        );
    END IF;
EXCEPTION WHEN OTHERS THEN
    INSERT INTO recruitment_service.trajectory_sync_errors (id_applc, id_evty, error_message)
    VALUES (p_related_id, p_id_evty, 'Table: ' || p_related_table || ' - Error: ' || SQLERRM);
END;
$$;


--
-- Name: trg_fn_log_apto_email(); Type: FUNCTION; Schema: recruitment_service; Owner: -
--

CREATE FUNCTION recruitment_service.trg_fn_log_apto_email() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Activamos solo cuando se registra el envío exitoso del correo
    IF (NEW.state = 2 AND 
        (OLD.metadata->'notifications'->>'entrevista_aprobada_mail') IS NULL AND 
        (NEW.metadata->'notifications'->>'entrevista_aprobada_mail') IS NOT NULL) THEN
        
        PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_applc, 3);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_fn_log_follow_up_trajectory(); Type: FUNCTION; Schema: recruitment_service; Owner: -
--

CREATE FUNCTION recruitment_service.trg_fn_log_follow_up_trajectory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 1. HITO 4 (CONTACTO): Siempre se registra al insertar el seguimiento.
    IF (TG_OP = 'INSERT') THEN
        PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 4, 'job_application');
    END IF;

    -- 2. HITO 20 (SEGUIMIENTO): Solo si el estado de la llamada CAMBIA y no es 'Pendiente'
    IF (NEW.answered_call IS NOT NULL AND NEW.answered_call != 'Pendiente') THEN
        IF (TG_OP = 'INSERT' OR OLD.answered_call IS NULL OR OLD.answered_call != NEW.answered_call) THEN
            PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 20, 'job_application');
        END IF;
    END IF;

    -- 3. HITO 18 (AGENDA): Solo si se asigna o se CAMBIA la fecha o el turno (Re-programación)
    IF (NEW.interview_date IS NOT NULL OR NEW.id_intshf IS NOT NULL) THEN
        IF (TG_OP = 'INSERT' 
            OR OLD.interview_date IS NULL OR OLD.interview_date != NEW.interview_date
            OR OLD.id_intshf IS NULL OR OLD.id_intshf != NEW.id_intshf) THEN
            
            PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 18, 'job_application');
        END IF;
    END IF;

    -- 4. HITO 19 (ENTREVISTA): Solo si el resultado de asistencia cambia
    IF (NEW.attended IS NOT NULL AND NEW.attended != 'Pendiente') THEN
        IF (TG_OP = 'INSERT' OR OLD.attended IS NULL OR OLD.attended != NEW.attended) THEN
            PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 19, 'job_application');
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: trg_fn_log_landing_trajectory(); Type: FUNCTION; Schema: recruitment_service; Owner: -
--

CREATE FUNCTION recruitment_service.trg_fn_log_landing_trajectory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 1, 'job_application');
    IF (NEW.state IN (2, 3)) THEN
        PERFORM recruitment_service.fn_log_ecosystem_trajectory(NEW.id_jbapp, 2, 'job_application');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: convert_amount(numeric, character, character, date); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.convert_amount(p_amount numeric, p_from character, p_to character, p_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT ROUND(p_amount * sales_service.get_exchange_rate(p_from, p_to, p_date), 2);
$$;


--
-- Name: fn_create_audit_incidents(); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.fn_create_audit_incidents() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_item  RECORD;
BEGIN
    -- Solo cuando se marca KO_MINOR o KO_CRITICAL
    IF NEW.audit_status IN ('KO_MINOR','KO_CRITICAL') AND
       OLD.audit_status = 'IN_PROGRESS' THEN
        -- Crear incidencia por cada ítem KO que tiene incidencia asociada
        FOR v_item IN
            SELECT ai.id_item, ai.observation, aci.ko_incident_id
            FROM sales_service.sales_order_audit_item ai
            JOIN sales_service.audit_checklist_item aci ON aci.id_item = ai.id_item
            WHERE ai.id_audit = NEW.id_audit
              AND ai.result = 'KO'
              AND aci.ko_incident_id IS NOT NULL
        LOOP
            INSERT INTO sales_service.order_incident
                (id_order, id_incident, incident_status, detected_by,
                 assigned_to_role, resolution_notes)
            VALUES
                (NEW.id_order, v_item.ko_incident_id, 'OPEN', NEW.audited_by,
                 'OPERACIONES', v_item.observation);
        END LOOP;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_incident_response_status(); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.fn_incident_response_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.response_type = 'CORRECTION' THEN
        UPDATE sales_service.order_incident
        SET incident_status = 'PENDING_RESPONSE'
        WHERE id_order_incident = NEW.id_order_incident
          AND incident_status = 'OPEN';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fn_log_order_status_change(); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.fn_log_order_status_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_actor BIGINT;
BEGIN
    IF (OLD.id_status IS DISTINCT FROM NEW.id_status)
    OR (OLD.id_substatus IS DISTINCT FROM NEW.id_substatus) THEN
        BEGIN
            v_actor := current_setting('app.current_user_id', true)::BIGINT;
        EXCEPTION WHEN OTHERS THEN
            v_actor := NEW.id_user;
        END;

        INSERT INTO sales_service.sales_order_status_history
            (id_order, order_date, from_status_id, to_status_id,
             from_substatus_id, to_substatus_id, changed_by)
        VALUES
            (NEW.id_order, CURRENT_DATE, OLD.id_status, NEW.id_status,
             OLD.id_substatus, NEW.id_substatus, v_actor);
    END IF;
    NEW.last_update := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;


--
-- Name: get_exchange_rate(character, character, date); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.get_exchange_rate(p_from character, p_to character, p_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
    SELECT rate
    FROM sales_service.exchange_rate
    WHERE from_currency = p_from
      AND to_currency   = p_to
      AND valid_from   <= p_date
      AND (valid_to IS NULL OR valid_to > p_date)
    ORDER BY valid_from DESC
    LIMIT 1;
$$;


--
-- Name: FUNCTION get_exchange_rate(p_from character, p_to character, p_date date); Type: COMMENT; Schema: sales_service; Owner: -
--

COMMENT ON FUNCTION sales_service.get_exchange_rate(p_from character, p_to character, p_date date) IS 'Retorna el tipo de cambio vigente para una fecha dada.
Uso: SELECT sales_service.get_exchange_rate(''EUR'', ''PEN'', ''2026-06-01'');
Retorna NULL si no hay tipo de cambio registrado para esa fecha.';


--
-- Name: validate_status_transition(bigint, bigint, text); Type: FUNCTION; Schema: sales_service; Owner: -
--

CREATE FUNCTION sales_service.validate_status_transition(p_from_status_id bigint, p_to_status_id bigint, p_role text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM sales_service.order_status_transition
        WHERE from_status_id = p_from_status_id
          AND to_status_id   = p_to_status_id
          AND p_role = ANY(allowed_roles)
          AND is_active = true
    );
$$;


--
-- Name: FUNCTION validate_status_transition(p_from_status_id bigint, p_to_status_id bigint, p_role text); Type: COMMENT; Schema: sales_service; Owner: -
--

COMMENT ON FUNCTION sales_service.validate_status_transition(p_from_status_id bigint, p_to_status_id bigint, p_role text) IS 'Valida si una transición de estado es permitida para un rol dado.
Uso: SELECT sales_service.validate_status_transition(3, 4, ''SUPERVISOR'');';


--
-- Name: fn_audit_trigger(); Type: FUNCTION; Schema: system_audit; Owner: -
--

CREATE FUNCTION system_audit.fn_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_old     jsonb;
    v_new     jsonb;
    v_id      text;
    v_user    text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
        IF v_old = v_new THEN RETURN NULL; END IF;
        -- Extraer PK: busca columna 'id' o la primera columna que empiece con 'id_'
        v_id := COALESCE(
            v_new->>'id',
            (SELECT value FROM jsonb_each_text(v_new)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    ELSIF TG_OP = 'DELETE' THEN
        v_old := to_jsonb(OLD);
        v_new := NULL;
        v_id := COALESCE(
            v_old->>'id',
            (SELECT value FROM jsonb_each_text(v_old)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    ELSIF TG_OP = 'INSERT' THEN
        v_old := NULL;
        v_new := to_jsonb(NEW);
        v_id := COALESCE(
            v_new->>'id',
            (SELECT value FROM jsonb_each_text(v_new)
             WHERE key LIKE 'id_%' ORDER BY key LIMIT 1)
        );
    END IF;

    -- Actor: intenta leer de variable de sesión (SET LOCAL app.current_user = 'username')
    BEGIN
        v_user := current_setting('app.current_user', true);
    EXCEPTION WHEN OTHERS THEN
        v_user := current_user;
    END;
    IF v_user IS NULL OR v_user = '' THEN v_user := current_user; END IF;

    INSERT INTO system_audit.audit_log
        (schema_name, table_name, operation, record_id, old_value, new_value, changed_by, register)
    VALUES
        (TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP, v_id, v_old, v_new, v_user, CURRENT_TIMESTAMP);

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


