--

CREATE TABLE knowledge_base.kb_article (
    id_article bigint NOT NULL,
    id_category bigint NOT NULL,
    id_cmpg bigint,
    title character varying(300) NOT NULL,
    slug character varying(300) NOT NULL,
    summary text,
    content text NOT NULL,
    content_type character varying(30) DEFAULT 'PROCEDURE'::character varying NOT NULL,
    target_roles text[] DEFAULT '{}'::text[] NOT NULL,
    version character varying(20) DEFAULT '1.0'::character varying NOT NULL,
    is_published boolean DEFAULT false NOT NULL,
    is_pinned boolean DEFAULT false NOT NULL,
    view_count integer DEFAULT 0 NOT NULL,
    helpful_count integer DEFAULT 0 NOT NULL,
    not_helpful_count integer DEFAULT 0 NOT NULL,
    created_by bigint NOT NULL,
    updated_by bigint,
    published_by bigint,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    published_at timestamp with time zone,
    deprecated_at timestamp with time zone
);


--
-- Name: TABLE kb_article; Type: COMMENT; Schema: knowledge_base; Owner: -
--

COMMENT ON TABLE knowledge_base.kb_article IS 'Artículos de la base de conocimientos. content en Markdown.
Un artículo puede ser un procedimiento, FAQ, script de llamada o texto legal.
id_cmpg NULL = aplica a todas las campañas.
Para textos legales, vincular a audit_checklist_item.expected_text.';


