--
-- Name: lead_pre_sale; Type: TABLE; Schema: lead_service; Owner: -
--

CREATE TABLE lead_service.lead_pre_sale (
    id_presale bigint NOT NULL,
    id_cmpg bigint,
    phone character varying(50) NOT NULL,
    operator character varying(100),
    first_name character varying(100),
    last_name character varying(100),
    address text,
    province character varying(100),
    coverage_status character varying(50),
    tentative_offer jsonb DEFAULT '{}'::jsonb NOT NULL,
    id_status bigint NOT NULL,
    owner_user_id bigint NOT NULL,
    current_user_id bigint,
    alert_after_days smallint DEFAULT 5 NOT NULL,
    last_activity_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    alerted_at timestamp with time zone,
    converted_to_order_id bigint,
    converted_at timestamp with time zone,
    converted_by bigint,
    discard_reason character varying(100),
    discarded_at timestamp with time zone,
    discarded_by bigint,
    notes text,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    assigned_advisor_1_id bigint,
    assigned_advisor_2_id bigint,
    assigned_advisor_3_id bigint,
    assignment_status character varying(30) DEFAULT 'NONE'::character varying,
    assigned_call_step integer DEFAULT 0,
    assignment_rejected_reason text,
    assignment_requested_at timestamp with time zone,
    assignment_responded_at timestamp with time zone,
    target_operator character varying(100),
    dni character varying(50),
    CONSTRAINT chk_phone_not_empty CHECK (((phone)::text <> ''::text))
);


--
-- Name: TABLE lead_pre_sale; Type: COMMENT; Schema: lead_service; Owner: -
--

COMMENT ON TABLE lead_service.lead_pre_sale IS 'El "papelito digital". Captura datos mínimos del cliente (teléfono, operador)
antes de abrir una venta formal. Se enriquece progresivamente en cada llamada
de compañía. Cuando el asesor decide avanzar, se convierte en sales_order
y los datos viajan pre-llenados. No genera porcentaje de cancelación.';


--
-- Name: COLUMN lead_pre_sale.tentative_offer; Type: COMMENT; Schema: lead_service; Owner: -
--

COMMENT ON COLUMN lead_service.lead_pre_sale.tentative_offer IS 'JSONB con la oferta que se va construyendo en las 3 llamadas:
{"company1": "Movistar", "offer1": "50Ôé¼ fibra+2móviles",
 "company2": "Vodafone", "offer2": "45Ôé¼ convergente",
 "company3": "Yoigo", "offer3": null, "accepted_company": "company2",
 "accepted_offer": "45Ôé¼ convergente"}';


--
-- Name: lead_pre_sale_assignment; Type: TABLE; Schema: lead_service; Owner: -
--

CREATE TABLE lead_service.lead_pre_sale_assignment (
    id_assignment bigint NOT NULL,
    id_presale bigint NOT NULL,
    from_user_id bigint NOT NULL,
    to_user_id bigint NOT NULL,
    assignment_type character varying(50) DEFAULT 'ASSIST'::character varying NOT NULL,
    reason text,
    context_notes text,
    is_active boolean DEFAULT true NOT NULL,
    assigned_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    returned_at timestamp with time zone,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: TABLE lead_pre_sale_assignment; Type: COMMENT; Schema: lead_service; Owner: -
--

COMMENT ON TABLE lead_service.lead_pre_sale_assignment IS 'Trazabilidad completa de derivaciones. ASSIST = Ronald ayuda a Chirlly
pero la venta sigue siendo de Chirlly (owner no cambia). TRANSFER = el
pre-sale cambia de dueño. COVER = cobertura por ausencia del asesor.';


