    exchange_rate_id bigint,
    exchange_rate_applied numeric(12,6),
    total_orders integer DEFAULT 0 NOT NULL,
    total_products integer DEFAULT 0 NOT NULL,
    status character varying(20) DEFAULT 'DRAFT'::character varying NOT NULL,
    approved_by bigint,
    approved_at timestamp with time zone,
    paid_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_cs_period CHECK ((period_start <= period_end)),
    CONSTRAINT chk_cs_status CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('APPROVED'::character varying)::text, ('PAID'::character varying)::text, ('DISPUTED'::character varying)::text])))
);


