    rate numeric(12,6) NOT NULL,
    valid_from date NOT NULL,
    valid_to date,
    source character varying(100) DEFAULT 'MANUAL'::character varying NOT NULL,
    created_by bigint,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_er_different CHECK ((from_currency <> to_currency)),
    CONSTRAINT chk_er_rate CHECK ((rate > (0)::numeric))
);


--
-- Name: TABLE exchange_rate; Type: COMMENT; Schema: sales_service; Owner: -
--

COMMENT ON TABLE sales_service.exchange_rate IS 'Historial de tipos de cambio con exclusión de períodos solapados.
Para convertir EUR ÔåÆ PEN: buscar el registro vigente en la fecha de la venta.
valid_to = NULL = tipo de cambio actual vigente.
El constraint EXCLUDE garantiza que no haya dos tipos de cambio solapados
para el mismo par de monedas.';


