CREATE TABLE sales_service.order_incident (
    id_order_incident bigint NOT NULL,
    id_order bigint NOT NULL,
    id_incident bigint,
    custom_name character varying(255),
    custom_description text,
    custom_solution text,
    incident_status character varying(30) DEFAULT 'OPEN'::character varying NOT NULL,
    detected_by bigint NOT NULL,
    assigned_to_role character varying(50) DEFAULT 'OPERACIONES'::character varying NOT NULL,
    resolved_by bigint,
    resolved_at timestamp with time zone,
    resolution_notes text,
    escalated_by bigint,
    escalated_at timestamp with time zone,
    escalation_reason text,
    due_at timestamp with time zone,
    register timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_oi_content CHECK (((id_incident IS NOT NULL) OR ((custom_name IS NOT NULL) AND (custom_description IS NOT NULL)))),
    CONSTRAINT chk_oi_status CHECK (((incident_status)::text = ANY (ARRAY[('OPEN'::character varying)::text, ('PENDING_RESPONSE'::character varying)::text, ('RESOLVED'::character varying)::text, ('ESCALATED'::character varying)::text, ('CLOSED'::character varying)::text])))
);


