-- Name: product_activation_tracking; Type: TABLE; Schema: sales_service; Owner: -
--

CREATE TABLE sales_service.product_activation_tracking (
    id_tracking bigint NOT NULL,
    id_order bigint NOT NULL,
    id_order_item bigint NOT NULL,
    product_name character varying(200) NOT NULL,
    id_provider bigint,
    provider_ref character varying(200),
    order_loaded_at timestamp with time zone,
    expected_activation_date date,
    actual_activation_date date,
    activation_status character varying(30) DEFAULT 'PENDING'::character varying NOT NULL,
    delay_days smallint GENERATED ALWAYS AS (
CASE
    WHEN ((actual_activation_date IS NOT NULL) AND (expected_activation_date IS NOT NULL) AND (actual_activation_date > expected_activation_date)) THEN (((actual_activation_date - expected_activation_date))::smallint)::integer
    ELSE 0
END) STORED,
    delay_reason text,
    alert_sent_at timestamp with time zone,
    last_checked_at timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT chk_pat_status CHECK (((activation_status)::text = ANY (ARRAY[('PENDING'::character varying)::text, ('IN_PROCESS'::character varying)::text, ('ACTIVATED'::character varying)::text, ('DELAYED'::character varying)::text, ('FAILED'::character varying)::text, ('CANCELLED'::character varying)::text])))
);


--
-- Name: TABLE product_activation_tracking; Type: COMMENT; Schema: sales_service; Owner: -
--

COMMENT ON TABLE sales_service.product_activation_tracking IS 'Seguimiento de activación por producto dentro de la misma orden.
Fibra, móvil 1, móvil 2 pueden tener SLAs diferentes. delay_days
se calcula automáticamente. Cuando delay_days > 0 y no se ha enviado
alerta, el sistema notifica al supervisor y al asesor.';


--
-- Name: product_activation_tracking_id_tracking_seq; Type: SEQUENCE; Schema: sales_service; Owner: -
--

ALTER TABLE sales_service.product_activation_tracking ALTER COLUMN id_tracking ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME sales_service.product_activation_tracking_id_tracking_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


