);


--
-- Name: COLUMN sales_form_field.validation_type; Type: COMMENT; Schema: sales_service; Owner: -
--

COMMENT ON COLUMN sales_service.sales_form_field.validation_type IS 'Tipo de validación:
IBAN_ES = IBAN español (ES + 22 dígitos)
DNI_ES  = DNI español (8 números + letra)
NIE_ES  = NIE (X/Y/Z + 7 números + letra)
CUPS_ENERGY = Código CUPS energía (ES + 20 chars)
PHONE_ES = Teléfono español (9 dígitos, empieza 6,7,8,9)
PROVINCE_ES = Desplegable de provincias españolas
CUSTOM = usa validation_regex de la columna existente';


